{
  "name": "unusual-seeds",
  "type": "module",
  "version": "0.0.1",
  "private": true,
  "scripts": {
    "dev": "astro dev",
    "build": "astro build",
    "preview": "astro preview",
    "check": "astro check"
  },
  "dependencies": {
    "@astrojs/mdx": "^4.2.0",
    "@astrojs/tailwind": "^6.0.2",
    "astro": "^5.7.10",
    "tailwindcss": "^3.4.17",
    "zod": "^3.24.2"
  },
  "devDependencies": {
    "@astrojs/check": "^0.9.4",
    "typescript": "^5.8.3"
  }
}

import { defineConfig } from "astro/config";
import mdx from "@astrojs/mdx";
import tailwind from "@astrojs/tailwind";

// https://astro.build/config
export default defineConfig({
  site: "https://unusual-seeds.com",
  integrations: [mdx(), tailwind({ applyBaseStyles: false })],
});

{
  "extends": "astro/tsconfigs/strict",
  "compilerOptions": {
    "baseUrl": ".",
    "paths": {
      "@/*": ["src/*"]
    }
  },
  "include": [".astro/types.d.ts", "**/*"],
  "exclude": ["dist"]
}

/** @type {import('tailwindcss').Config} */
export default {
  content: ["./src/**/*.{astro,html,js,jsx,md,mdx,svelte,ts,tsx,vue}"],
  theme: {
    extend: {
      colors: {
        "blue-hour": {
          sky: "#1e3a5f",
          deep: "#0f1c2e",
          mist: "#2d4a6a",
        },
        conservatory: {
          glow: "#d4b87a",
          warm: "#c9a962",
        },
        ink: {
          DEFAULT: "#0a1018",
          soft: "#141c28",
        },
      },
      fontFamily: {
        serif: [""Crimson Pro"", "Georgia", "serif"],
        sans: [""Source Sans 3"", "system-ui", "sans-serif"],
      },
    },
  },
  plugins: [],
};

import { defineCollection, z } from "astro:content";
import { glob } from "astro/loaders";

/** Biome slugs used in frontmatter — keep in sync with src/data/biomes.ts */
export const biomeSlugs = [
  "conservatory-of-futures",
  "house-of-imagined-worlds",
  "earth-and-ecology",
  "wonder-and-wander",
  "rare-specimens",
] as const;

const seeds = defineCollection({
  loader: glob({ pattern: "**/*.{md,mdx}", base: "./src/content/seeds" }),
  schema: z.object({
    title: z.string(),
    description: z.string(),
    biome: z.enum(biomeSlugs),
    pubDate: z.coerce.date(),
    draft: z.boolean().default(false),
  }),
});

export const collections = { seeds };

/**
 * Site biomes — single source of truth for navigation and placeholder pages.
 * Beginners: edit titles and descriptions here; pages update automatically.
 */
export type BiomeSlug =
  | "conservatory-of-futures"
  | "house-of-imagined-worlds"
  | "earth-and-ecology"
  | "wonder-and-wander"
  | "rare-specimens";

export interface Biome {
  slug: BiomeSlug;
  title: string;
  shortTitle: string;
  description: string;
  placeholder: string;
}

export const biomes: Biome[] = [
  {
    slug: "conservatory-of-futures",
    title: "Conservatory of Futures",
    shortTitle: "Futures",
    description:
      "Thoughtful ideas about technology, intelligence, and the choices shaping tomorrow.",
    placeholder:
      "Essays and notes on future thinking — without hype or doom.",
  },
  {
    slug: "house-of-imagined-worlds",
    title: "House of Imagined Worlds",
    shortTitle: "Fiction",
    description:
      "Science fiction, imagined civilizations, and stories that help us see our own world.",
    placeholder:
      "Books, shows, and ideas worth exploring from imagined futures.",
  },
  {
    slug: "earth-and-ecology",
    title: "Earth & Ecology",
    shortTitle: "Ecology",
    description:
      "Biology, climate optimism, ecosystems, and our place on a living planet.",
    placeholder:
      "Nature writing grounded in curiosity and care.",
  },
  {
    slug: "wonder-and-wander",
    title: "Wonder & Wander",
    shortTitle: "Wonder",
    description:
      "Travel, culture, places, and experiences that expand perspective.",
    placeholder:
      "Journeys and discoveries from the edges of the map.",
  },
  {
    slug: "rare-specimens",
    title: "Rare Specimens",
    shortTitle: "Specimens",
    description:
      "Unusual discoveries, rabbit holes, and ideas from the margins.",
    placeholder:
      "Curious finds worth preserving in the archive.",
  },
];

export function getBiome(slug: string): Biome | undefined {
  return biomes.find((b) => b.slug === slug);
}

@tailwind base;
@tailwind components;
@tailwind utilities;

@layer base {
  html {
    @apply scroll-smooth antialiased;
  }

  body {
    @apply bg-ink text-conservatory-glow/90 font-sans;
  }

  h1,
  h2,
  h3 {
    @apply font-serif font-normal tracking-wide text-conservatory-glow;
  }

  a {
    @apply transition-colors duration-200;
  }
}

---
